def top_k(lst, k):

    if lst == []:
        return lst

    lower = []

    while lst:
        lower.append(max(lst))
        lst.remove(max(lst))
        for higher in lst:
            if higher in lower:
                lower.append(higher)
                lst.remove(higher)
    return lower[:k]

